"""Patches the android/ folder generated by `flutter create`.

Safe to run more than once. It
  * adds INTERNET (preview server + online library) and storage permissions
    (so the editor can open real folders on the phone),
  * allows cleartext HTTP to 127.0.0.1/localhost only,
  * sets the app name to "Decode",
  * installs the Decode launcher icon (legacy + adaptive).
"""
import pathlib
import re
import shutil
import sys

main = pathlib.Path("android/app/src/main")
manifest = main / "AndroidManifest.xml"
if not manifest.exists():
    sys.exit("android/ not found - run `flutter create` first")

text = manifest.read_text(encoding="utf-8")

permissions = [
    '<uses-permission android:name="android.permission.INTERNET"/>',
    '<uses-permission android:name="android.permission.READ_EXTERNAL_STORAGE" android:maxSdkVersion="32"/>',
    '<uses-permission android:name="android.permission.WRITE_EXTERNAL_STORAGE" android:maxSdkVersion="29"/>',
    '<uses-permission android:name="android.permission.MANAGE_EXTERNAL_STORAGE"/>',
]
for permission in permissions:
    name = re.search(r'android:name="([^"]+)"', permission).group(1)
    if name not in text:
        text = text.replace("<application", permission + "\n    <application", 1)

def add_attr(source, attr, value):
    if attr in source:
        return source
    return source.replace(
        "<application", f'<application\n        {attr}="{value}"', 1
    )

text = add_attr(text, "android:networkSecurityConfig", "@xml/network_security_config")
text = add_attr(text, "android:requestLegacyExternalStorage", "true")
text = add_attr(text, "android:usesCleartextTraffic", "false")
text = re.sub(r'android:label="[^"]*"', 'android:label="Decode"', text, count=1)
if 'android:icon="@mipmap/ic_launcher"' not in text:
    text = re.sub(r'android:icon="[^"]*"', 'android:icon="@mipmap/ic_launcher"', text, count=1)
manifest.write_text(text, encoding="utf-8")

xml_dir = main / "res" / "xml"
xml_dir.mkdir(parents=True, exist_ok=True)
(xml_dir / "network_security_config.xml").write_text(
    """<?xml version="1.0" encoding="utf-8"?>
<network-security-config>
    <domain-config cleartextTrafficPermitted="true">
        <domain includeSubdomains="false">127.0.0.1</domain>
        <domain includeSubdomains="false">localhost</domain>
    </domain-config>
</network-security-config>
""",
    encoding="utf-8",
)

shutil.copytree("tool/android_res", main / "res", dirs_exist_ok=True)

print("Android project patched")
print([l.strip() for l in text.splitlines() if "android:icon" in l or "android:label" in l])
